insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('church-branding','church-branding',true,5242880,array['image/png','image/jpeg','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/png','image/jpeg','image/webp'];
create policy church_branding_admin_upload on storage.objects for insert to authenticated with check(bucket_id='church-branding' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin')));
create policy church_branding_admin_update on storage.objects for update to authenticated using(bucket_id='church-branding' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin'))) with check(bucket_id='church-branding' and exists(select 1 from public.church_members cm where cm.church_id::text=(storage.foldername(name))[1] and cm.user_id=(select auth.uid()) and cm.status='active' and cm.role in('owner','admin')));
